export function createStockCorrectionEditors({api,h,mount,input,area,select}){
 async function stockCorrection(id,voided=false){
  const s=await api.stockCorrection(id),d=s.document,key=crypto.randomUUID();if(d.status==='void')throw Error('原单据已作废。');if(voided&&s.lines.some(l=>l.quantityLocked))throw Error('原单后已有盘点或人工纠错，请先核对后续调整，不能再次冲回数量。');
  const body=`<p>${h(d.businessDate)} · ${h(d.sourceReference||'原商品单据')} · ${h({inbound:'入库',shipment:'发货',return:'可售退货'}[d.operation])}</p>`+(voided?'<p>只用于错误登记。将按原归属追加数量冲回，保留原流水；有真实退货或数量已被盘点校正时会拒绝。作废不代表实际退货或撤销付款，采购金额与支出仍保留原历史。</p>':input('businessDate','正确业务日期',d.businessDate,'required type="date"')+input('sourceReference','正确来源参考',d.sourceReference,'maxlength="200"')+
   s.lines.map((l,i)=>`<fieldset><legend>${h(l.snapshot.skuCode)} · ${h(l.snapshot.name)} · ${h(l.snapshot.storeName||'公共库存')}</legend><p>原有效单据数量 ${l.quantity} · 当前此归属库存 ${l.currentQuantity} ${h(l.snapshot.unit)}</p>`+input('quantity'+i,'正确单据数量',l.quantity,'required type="number" min="1" max="2147483647" step="1"'+(l.quantityLocked?' readonly':''))+(l.quantityLocked?'<p class="muted">原单之后已有盘点或人工纠错，数量可能已校正，此处只更正业务信息。</p>':'')+(l.inventoryStoreId||d.operation==='return'?`<p>业务店铺 ${h(l.snapshot.businessStoreName||'原业务店铺')}，沿用原归属／原发货。</p>`:select('store'+i,d.operation==='shipment'?'正确发货业务店铺':'业务店铺（可空）',l.businessStoreId||'',[['','不指定'],...s.stores.map(v=>[v.id,v.name+(v.active?'':'（已停用）')])]))+'</fieldset>').join('')+'<p class="muted">只更正原明细数量、日期和允许变更的业务归属，不换商品或库存来源。数量差额会追加新流水；入库单更正后，采购成本需从原入口重新核对。保存前会校验真实退货、现存数量及按业务日期重放的库存。</p>')+area('reason',voided?'错误内容与作废依据（必填）':'原错误内容和更正依据（必填）');
  mount(voided?'作废错误商品单据':'更正商品单据',body,f=>api.saveStockCorrection(id,voided?{requestKey:key,expectedVersion:d.version,token:s.token,reason:f.get('reason')}:{requestKey:key,expectedVersion:d.version,token:s.token,businessDate:f.get('businessDate'),sourceReference:f.get('sourceReference'),reason:f.get('reason'),lines:s.lines.map((l,i)=>({movementId:l.id,quantity:Number(f.get('quantity'+i)),businessStoreId:l.inventoryStoreId||d.operation==='return'?l.businessStoreId:f.get('store'+i)||null}))},voided),{kind:'stock-correction',id},()=>api.stockCorrectionReceipt(id,key,voided));
 }
 return {stockCorrection};
}
